export const getGetProjectProductsUrl = (projectId: number,
    params?: GetProjectProductsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/projects/${projectId}/products?${stringifiedParams}` : `/api/projects/${projectId}/products`
}

